/*saveSellerMpRqQuotaList_v2*/
UPDATE	KEPQTDT A
SET		STOA_LIST_PRICE = DECODE(A.TAX_TYPE, '12', #{ORG_STOA_LIST_PRICE}, DECODE(A.VAT_YN, 'Y', ROUND(#{ORG_STOA_LIST_PRICE}*1.1), #{ORG_STOA_LIST_PRICE}))
		, ORG_STOA_LIST_PRICE = #{ORG_STOA_LIST_PRICE}
		, LEAD_TIME = #{LEAD_TIME}
		, STOA_REMARK = #{STOA_REMARK}
		, SELLER_IMAGE_KEY = #{SELLER_IMAGE_KEY}
		, MIN_ORDER_QTY = DECODE(#{MIN_ORDER_QTY}, '', 1, #{MIN_ORDER_QTY})
		, PUR_UNIT_QTY = DECODE(#{PUR_UNIT_QTY}, '', 1, #{PUR_UNIT_QTY})
		, SELLER_AREA = #{SELLER_AREA}
		, PROCESS_TYPE = #{PROCESS_TYPE}
		, IMGFILE_DIR = #{IMGFILE_DIR}
		, IMGFILE_NAME = #{IMGFILE_NAME}
		, TAX_TYPE = DECODE(#{TAX_TYPE}, '', '11', #{TAX_TYPE})
		, ITEM_MAKE_TYPE = #{ITEM_MAKE_TYPE}
		, PRE_GR_FLAG = #{PRE_GR_FLAG}
		, SELLER_ITEM_NO = #{SELLER_ITEM_NO}   
WHERE	1=1
AND		BUYER = #{BUYER}
AND		QUOTATION_NO = #{QUOTATION_NO}
AND		QUOTATION_SEQ = #{QUOTATION_SEQ}
AND		REVISION = #{REVISION}
AND		AGENT = #{AGENT}
AND		AGENT_REVISION = #{AGENT_REVISION}

